fun main() { val promptText = "Python"; val escapedPrompt = promptText.replace("\"", "\\\"").replace("\n", " "); val fullPrompt = "Generate a study plan for \\\"$escapedPrompt\\\". Return ONLY valid JSON: {\\\"courseName\\\": \\\"Name\\\", \\\"subtopics\\\": [{\\\"name\\\": \\\"Topic\\\", \\\"days\\\": 2}]}"; val jsonBody = """{ "model": "llama-3.1-8b-instant", "messages": [ {"role": "system", "content": "You are a helpful study planner. Always return raw JSON only, no markdown blocks."}, {"role": "user", "content": "$fullPrompt"} ], "response_format": {"type": "json_object"} }""".trimIndent(); println(jsonBody) }
